window.COMPONENTS = {
  "navbar": "<canvas id=\"bg-canvas\"></canvas>\n\n<nav>\n  <button class=\"btn sm gh mobile-menu-toggle\" type=\"button\" onclick=\"toggleMobileMenu()\" aria-label=\"Mở danh mục điều hướng\" aria-controls=\"mobile-sidebar\" aria-expanded=\"false\" title=\"Danh mục điều hướng\">\n    <span>☰</span> <span class=\"nav-btn-label\">Danh mục</span>\n  </button>\n\n  <div class=\"brand-wrap\" onclick=\"go('home')\" aria-label=\"Về Trang chủ\">\n    <img class=\"brand-logo\" src=\"./assets/logo-nguvan.png\" alt=\"Biểu trưng Ngữ Văn\">\n  </div>\n</nav>\n\n<div class=\"mobile-menu-backdrop\" onclick=\"closeMobileMenu()\" aria-hidden=\"true\"></div>\n<aside class=\"mobile-sidebar\" id=\"mobile-sidebar\" aria-label=\"Danh mục điều hướng\" aria-hidden=\"true\">\n  <div class=\"mobile-sidebar-header\">\n    <div style=\"display:flex;align-items:center;cursor:pointer;\" onclick=\"go('home'); closeMobileMenu();\" title=\"Về trang chủ\">\n      <img src=\"./assets/logo-nguvan.png\" alt=\"Biểu trưng Ngữ Văn\" class=\"sidebar-logo\">\n    </div>\n    <button class=\"btn sm gh\" type=\"button\" onclick=\"closeMobileMenu()\" aria-label=\"Đóng danh mục\">✕</button>\n  </div>\n  <div class=\"sidebar-links-list\">\n    <a data-g=\"home\" onclick=\"go('home'); closeMobileMenu();\">\n      <span class=\"sidebar-icon\">🏠</span> <span>Trang chủ</span>\n    </a>\n    <a data-g=\"setup\" onclick=\"go('setup'); closeMobileMenu();\">\n      <span class=\"sidebar-icon\">📖</span> <span>Bài học</span>\n    </a>\n    <a data-g=\"reading\" onclick=\"go('reading'); closeMobileMenu();\">\n      <span class=\"sidebar-icon\">📑</span> <span>Đọc hiểu</span>\n    </a>\n    <a data-g=\"writing\" onclick=\"go('writing'); closeMobileMenu();\">\n      <span class=\"sidebar-icon\">✍️</span> <span>Luyện viết</span>\n    </a>\n    <a data-g=\"lib\" onclick=\"go('lib'); closeMobileMenu();\">\n      <span class=\"sidebar-icon\">📚</span> <span>Thư viện</span>\n    </a>\n    <a onclick=\"closeMobileMenu(); openSettingsDialog();\">\n      <span class=\"sidebar-icon\">⚙️</span> <span>Cài đặt</span>\n    </a>\n  </div>\n</aside>",
  "settings-dialog": "<!-- SETTINGS DIALOG -->\n<dialog id=\"settings-dialog\" class=\"settings-modal\">\n  <div class=\"settings-header\">\n    <div class=\"settings-title-wrap\">\n      <span class=\"settings-icon\">⚙️</span>\n      <h3>Cài đặt</h3>\n    </div>\n    <button class=\"btn sm gh\" type=\"button\" onclick=\"closeSettingsDialog()\" aria-label=\"Đóng cài đặt\">✕</button>\n  </div>\n  <div class=\"settings-body\" style=\"overflow-y: auto; -webkit-overflow-scrolling: touch;\">\n    <!-- Hiệu ứng âm thanh -->\n    <div class=\"settings-item\">\n      <div class=\"settings-item-info\">\n        <div class=\"settings-item-icon\">🔊</div>\n        <div>\n          <div class=\"settings-item-name\">Hiệu ứng âm thanh</div>\n          <div class=\"settings-item-desc\">Âm thanh khi chọn đáp án và thao tác</div>\n        </div>\n      </div>\n      <button class=\"btn sm\" id=\"btn-setting-sound\" onclick=\"toggleSound()\">Bật</button>\n    </div>\n    <!-- Giao diện Sáng / Tối -->\n    <div class=\"settings-item\">\n      <div class=\"settings-item-info\">\n        <div class=\"settings-item-icon\">🌗</div>\n        <div>\n          <div class=\"settings-item-name\">Giao diện (Sáng / Tối)</div>\n          <div class=\"settings-item-desc\">Chuyển đổi giao diện Sáng hoặc Tối</div>\n        </div>\n      </div>\n      <button class=\"btn sm gh\" id=\"btn-setting-theme\" onclick=\"toggleTheme()\">Sáng</button>\n    </div>\n    <!-- Chế độ Máy chiếu -->\n    <div class=\"settings-item\">\n      <div class=\"settings-item-info\">\n        <div class=\"settings-item-icon\">🖥️</div>\n        <div>\n          <div class=\"settings-item-name\">Chế độ máy chiếu</div>\n          <div class=\"settings-item-desc\">Tăng kích thước chữ hiển thị trên máy chiếu</div>\n        </div>\n      </div>\n      <button class=\"btn sm gh\" id=\"btn-setting-projector\" onclick=\"toggleProjectorMode()\">Tắt</button>\n    </div>\n  </div>\n  <div class=\"settings-footer\">\n    <button class=\"btn au\" type=\"button\" onclick=\"closeSettingsDialog()\">Hoàn tất</button>\n  </div>\n</dialog>",
  "screen-home": "<!-- SCREEN 1: HOME -->\n<section id=\"s-home\" class=\"scr\">\n  <div class=\"wrap\">\n    <!-- HERO SHOWCASE -->\n    <div class=\"hero-showcase\" id=\"hero-showcase\">\n      <div class=\"hero-study-card\" id=\"hero-study-card\">\n        <div class=\"study-card-img-wrap\" id=\"study-img-wrap\">\n          <img class=\"study-card-img\" id=\"study-img\" src=\"./assets/bac-ho.jpg\" alt=\"Chủ tịch Hồ Chí Minh\">\n        </div>\n        <div class=\"study-card-content\" id=\"study-content\">\n          <div class=\"study-quote-tag\" id=\"study-tag\">Lời dạy của Bác Hồ</div>\n          <div class=\"study-main-quote long-quote\" id=\"study-quote\">“Non sông Việt Nam có trở nên tươi đẹp hay không, dân tộc Việt Nam có bước tới đài vinh quang để sánh vai với các cường quốc năm châu được hay không, chính là nhờ một phần lớn ở công học tập của các em.”</div>\n          <div class=\"study-quote-author\" id=\"study-author\">— Chủ tịch Hồ Chí Minh —</div>\n        </div>\n      </div>\n    </div>\n\n    <!-- LEADERBOARD -->\n    <div class=\"card lb-card\" style=\"padding:24px 28px;\">\n      <div class=\"lb-header-bar\">\n        <div class=\"lb-title-wrap\">\n          <span class=\"lb-trophy-icon\">🏆</span>\n          <div>\n            <h2 class=\"lb-heading\">Bảng Vàng Vinh Danh Học Sinh</h2>\n            <p class=\"lb-subheading\">Thành tích qua các lượt bài học và kiểm tra</p>\n          </div>\n        </div>\n        <button class=\"btn gh sm lb-filter-reset\" onclick=\"R.home()\" title=\"Làm mới bảng xếp hạng\">↻ Làm mới</button>\n      </div>\n      <div class=\"lb-filters\">\n        <div class=\"lb-search-wrap\">\n          <input id=\"lb-search\" class=\"lb-search-input\" placeholder=\"🔍 Tìm kiếm theo tên học sinh, lớp, bộ đề...\" oninput=\"renderLeaderboard()\">\n        </div>\n        <select id=\"lb-mode-filter\" class=\"lb-mode-select\" onchange=\"renderLeaderboard()\" style=\"display:none;\">\n          <option value=\"\">Tất cả kết quả</option>\n        </select>\n        <button class=\"btn gh sm lb-filter-reset\" onclick=\"resetLbFilters()\">✕ Xóa lọc</button>\n      </div>\n      <div id=\"lb-container\"></div>\n    </div>\n  </div>\n</section>",
  "screen-lib": "<!-- SCREEN 2: LIBRARY / EDITOR -->\n<section id=\"s-lib\" class=\"scr\">\n  <div class=\"wrap\">\n    <div id=\"lv\">\n      <!-- Library Hero Banner -->\n      <div class=\"cartoon-lib-banner\">\n        <div class=\"lib-banner-content\">\n          <h1 style=\"font-size:clamp(22px, 3.5vw, 28px); margin:0 0 4px; font-weight:800;\">Kho học liệu &amp; Đề thi</h1>\n          <p class=\"mut\" style=\"margin:0; font-size:14.5px;\">Quản lý tập trung các bộ đề Bài học, Đọc hiểu và Luyện viết</p>\n        </div>\n        <span id=\"sync-badge\" class=\"sync-badge\" aria-live=\"polite\">☁️ Đã đồng bộ</span>\n      </div>\n\n      <!-- Segmented Tabs for 3 Sections -->\n      <div class=\"lib-tabs-bar\" role=\"tablist\" aria-label=\"Phân loại kho học liệu\">\n        <button class=\"lib-tab-btn active\" id=\"tab-btn-lessons\" data-tab=\"lessons\" type=\"button\" onclick=\"switchLibTab('lessons')\">\n          <span>📖</span>\n          <span>Bộ đề Bài học</span>\n          <span class=\"lib-tab-badge\" id=\"lib-lessons-badge\">0</span>\n        </button>\n        <button class=\"lib-tab-btn\" id=\"tab-btn-reading\" data-tab=\"reading\" type=\"button\" onclick=\"switchLibTab('reading')\">\n          <span>📑</span>\n          <span>Bộ đề Đọc hiểu</span>\n          <span class=\"lib-tab-badge\" id=\"lib-reading-badge\">0</span>\n        </button>\n        <button class=\"lib-tab-btn\" id=\"tab-btn-writing\" data-tab=\"writing\" type=\"button\" onclick=\"switchLibTab('writing')\">\n          <span>✍️</span>\n          <span>Bộ đề Viết</span>\n          <span class=\"lib-tab-badge\" id=\"lib-writing-badge\">0</span>\n        </button>\n      </div>\n\n      <!-- PANE 1: BỘ ĐỀ BÀI HỌC -->\n      <div id=\"lib-pane-lessons\" class=\"lib-tab-pane active\">\n        <div class=\"hud\" style=\"justify-content:flex-end;\">\n          <button class=\"btn au\" onclick=\"newSet()\">+ Tạo bộ mới</button>\n          <button class=\"btn cy\" onclick=\"openPromptDialog()\">🪄 Tạo bằng trợ lý AI</button>\n          <button id=\"bulk-delete-start\" class=\"btn no\" onclick=\"enableBulkDeleteMode()\">🗑️ Xóa nhiều</button>\n          <div id=\"bulk-delete-actions\" hidden>\n            <button id=\"bulk-delete\" class=\"btn no\" onclick=\"deleteSelectedSets()\" disabled>🗑️ Xóa đã chọn (0)</button>\n            <button class=\"btn gh\" onclick=\"cancelBulkDeleteMode()\">Hủy</button>\n          </div>\n        </div>\n        <!-- Search & Topic Tags Filter -->\n        <div class=\"lib-search-filter-card\">\n          <div class=\"lib-search-bar-row\">\n            <div class=\"lib-search-input-box\">\n              <span class=\"lib-search-lead-icon\">🔍</span>\n              <input id=\"lf\" type=\"text\" placeholder=\"Tìm kiếm bộ đề bài học theo tên, thẻ chủ đề…\" oninput=\"onLibSearchInput()\" autocomplete=\"off\">\n              <button id=\"lf-clear\" class=\"lib-search-clear-btn\" type=\"button\" onclick=\"clearLibSearch()\" aria-label=\"Xóa tìm kiếm\" hidden>✕</button>\n            </div>\n          </div>\n          <div class=\"topic-filter-row\">\n            <div class=\"topic-filter-meta\">\n              <span class=\"topic-filter-title\">Lọc theo thẻ chủ đề:</span>\n              <span id=\"topic-filter-summary\" class=\"topic-filter-summary\"></span>\n            </div>\n            <div id=\"topic-chips-bar\" class=\"topic-chips-bar\" role=\"tablist\" aria-label=\"Bộ lọc thẻ chủ đề\"></div>\n          </div>\n        </div>\n        <div class=\"setup-sets-grid\" id=\"lg\"></div>\n      </div>\n\n      <!-- PANE 2: BỘ ĐỀ ĐỌC HIỂU -->\n      <div id=\"lib-pane-reading\" class=\"lib-tab-pane\">\n        <div class=\"hud\" style=\"justify-content:flex-end;\">\n          <button class=\"btn au\" onclick=\"openCreateReadingSetModal()\">+ Thêm đề đọc hiểu mới</button>\n          <button class=\"btn cy\" onclick=\"promptAddNewReadingCategory()\">+ Thêm chủ đề</button>\n        </div>\n        <div class=\"lib-search-filter-card\">\n          <div class=\"lib-search-bar-row\">\n            <div class=\"lib-search-input-box\">\n              <span class=\"lib-search-lead-icon\">🔍</span>\n              <input id=\"lib-reading-search\" type=\"text\" placeholder=\"Tìm kiếm bộ đề đọc hiểu theo tên tác phẩm, tác giả...\" oninput=\"onLibReadingSearchInput()\" autocomplete=\"off\">\n            </div>\n          </div>\n          <div class=\"topic-filter-row\">\n            <div class=\"topic-filter-meta\">\n              <span class=\"topic-filter-title\">Lọc theo chủ đề:</span>\n              <span id=\"lib-reading-topic-summary\" class=\"topic-filter-summary\"></span>\n            </div>\n            <div id=\"lib-reading-chips-bar\" class=\"topic-chips-bar\" role=\"tablist\" aria-label=\"Bộ lọc chủ đề đọc hiểu\"></div>\n          </div>\n        </div>\n        <div class=\"setup-sets-grid\" id=\"lib-reading-grid\"></div>\n      </div>\n\n      <!-- PANE 3: BỘ ĐỀ VIẾT -->\n      <div id=\"lib-pane-writing\" class=\"lib-tab-pane\">\n        <div class=\"hud\" style=\"justify-content:flex-end;\">\n          <button class=\"btn au\" onclick=\"openCreateWritingSetModal()\">+ Thêm đề viết mới</button>\n          <button class=\"btn cy\" onclick=\"promptAddNewCategory()\">+ Thêm chủ đề</button>\n        </div>\n        <div class=\"lib-search-filter-card\">\n          <div class=\"lib-search-bar-row\">\n            <div class=\"lib-search-input-box\">\n              <span class=\"lib-search-lead-icon\">🔍</span>\n              <input id=\"lib-writing-search\" type=\"text\" placeholder=\"Tìm kiếm bộ đề viết theo tiêu đề, dạng đề...\" oninput=\"onLibWritingSearchInput()\" autocomplete=\"off\">\n            </div>\n          </div>\n          <div class=\"topic-filter-row\">\n            <div class=\"topic-filter-meta\">\n              <span class=\"topic-filter-title\">Lọc theo chủ đề:</span>\n              <span id=\"lib-writing-topic-summary\" class=\"topic-filter-summary\"></span>\n            </div>\n            <div id=\"lib-writing-chips-bar\" class=\"topic-chips-bar\" role=\"tablist\" aria-label=\"Bộ lọc chủ đề viết\"></div>\n          </div>\n        </div>\n        <div class=\"setup-sets-grid\" id=\"lib-writing-grid\"></div>\n      </div>\n    </div>\n\n    <!-- EDITOR VIEW -->\n    <div id=\"ev\" hidden>\n      <button class=\"btn gh sm\" style=\"margin-bottom:12px;\" onclick=\"go('lib')\">← Quay lại thư viện</button>\n      <div class=\"hud\">\n        <h1 style=\"font-size:26px; margin:0;\">Soạn thảo bộ câu hỏi</h1>\n      </div>\n      <div class=\"card\">\n        <div class=\"g2\">\n          <label>Tên bộ câu hỏi<input id=\"et\" oninput=\"meta()\"></label>\n          <label>Chủ đề / Bài học<input id=\"ec\" oninput=\"meta()\"></label>\n        </div>\n        <div style=\"display:flex;align-items:center;gap:10px;margin-top:12px;flex-wrap:wrap;\">\n          <span style=\"font-weight:700;\">Biểu tượng bộ đề:</span>\n          <button class=\"emoji-trigger\" type=\"button\" onclick=\"toggleEmojiPicker()\" id=\"emoji-trigger-btn\"><span id=\"current-emo\">📖</span> ▾ Chọn biểu tượng</button>\n        </div>\n        <div class=\"emoji-picker\" id=\"emoji-picker\"></div>\n      </div>\n\n      <div class=\"g2\" style=\"margin-top:16px; align-items:start;\">\n        <div class=\"card question-list-card\">\n          <h3 style=\"margin-bottom:10px;\">Danh sách câu hỏi (<span id=\"en\"></span>)</h3>\n          <input id=\"ef\" oninput=\"renderQs()\" placeholder=\"🔍 Tìm câu hỏi…\">\n          <div id=\"el\" style=\"margin-top:12px;\"></div>\n        </div>\n\n        <div class=\"card\">\n          <h3 id=\"eh\">Thêm câu hỏi mới</h3>\n          <div class=\"tabs\" id=\"ty\" style=\"display:flex; flex-wrap:wrap; gap:6px; margin-bottom:12px;\"></div>\n          \n          <label>Nội dung câu hỏi\n            <textarea id=\"fc\" placeholder=\"Nội dung câu hỏi (mặc định với dạng Đúng/Sai: Phát biểu sau đây là đúng?)\"></textarea>\n          </label>\n\n          <div data-t=\"tf\">\n            <label>Văn bản / Ngữ liệu đọc hiểu (không bắt buộc)\n              <textarea id=\"tf-passage\" style=\"min-height:85px;\" placeholder=\"Dán văn bản ngữ liệu, trích đoạn văn học nếu câu hỏi cần đọc hiểu...\"></textarea>\n            </label>\n            <div style=\"font-size:12.5px; color:var(--mut); margin:2px 0 10px;\">\n              Nếu để trống câu hỏi phía trên, hệ thống sẽ mặc định là: <b>\"Phát biểu sau đây là đúng?\"</b>\n            </div>\n            <label style=\"font-weight:700; margin-bottom:6px; display:block;\">4 phát biểu (nhấp chọn phát biểu Đúng / Sai):</label>\n            <div id=\"tf-items-editor\" class=\"tf-editor-container\"></div>\n          </div>\n\n          <div data-t=\"mc img\">\n            <label>4 phương án (đáp án đúng sẽ chọn sau khi thêm câu)</label>\n            <div id=\"fo\" class=\"option-editor\"></div>\n          </div>\n          \n          <div data-t=\"img\">\n            <label>Tải ảnh minh họa (PNG/JPG/WebP, &lt;1.5MB)\n              <input type=\"file\" accept=\"image/png,image/jpeg,image/webp\" onchange=\"pickImg(this)\">\n            </label>\n            <img id=\"fi\" class=\"qi\" hidden>\n          </div>\n          \n          <div data-t=\"short fill\">\n            <label>Đáp án chấp nhận (cách nhau bởi dấu |)<input id=\"fk\" placeholder=\"Hồ Chí Minh | Nguyễn Ái Quốc\"></label>\n          </div>\n          \n          <div data-t=\"match\">\n            <label>Các cặp ghép nối (mỗi dòng \"Vế 1 | Vế 2\")<textarea id=\"fp\"></textarea></label>\n          </div>\n          \n          <label>Lời giải thích chi tiết<textarea id=\"fe\" style=\"min-height:60px\"></textarea></label>\n          \n          <div class=\"g2\">\n            <label>Độ khó\n              <select id=\"fd\">\n                <option>Dễ</option>\n                <option>Trung bình</option>\n                <option>Khó</option>\n              </select>\n            </label>\n            <label>Nguồn trích dẫn<input id=\"fs\"></label>\n          </div>\n          \n          <div style=\"display:flex; gap:10px; margin-top:16px;\">\n            <button id=\"qsave\" class=\"btn au\" onclick=\"saveQ()\">💾 Thêm câu hỏi vào bộ</button>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>",
  "screen-setup": "<!-- SCREEN 3: SETUP & LESSONS (BÀI HỌC) -->\r\n<section id=\"s-setup\" class=\"scr\">\r\n  <div class=\"wrap\">\r\n    <!-- Hero Banner -->\r\n    <div class=\"cartoon-lib-banner setup-hero-banner\">\r\n      <div class=\"lib-banner-content\">\r\n        <h1 style=\"font-size:clamp(22px, 3.5vw, 28px); margin:0 0 4px; font-weight:800;\">Phòng bài học trắc nghiệm</h1>\r\n        <p class=\"mut\" style=\"margin:0; font-size:14.5px;\">Chọn bộ đề bài học bên dưới để bắt đầu luyện tập và thử thách kiến thức</p>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Search & Topic Filter Card -->\r\n    <div class=\"lib-search-filter-card\" style=\"margin: 0 0 16px;\">\r\n      <div class=\"lib-search-bar-row\">\r\n        <div class=\"lib-search-input-box\">\r\n          <span class=\"lib-search-lead-icon\">🔍</span>\r\n          <input id=\"setup-search\" type=\"text\" placeholder=\"Tìm kiếm bộ đề bài học theo tên, tác phẩm, chủ đề…\" oninput=\"onSetupSearchInput()\" autocomplete=\"off\">\r\n        </div>\r\n      </div>\r\n      <div class=\"topic-filter-row\" style=\"margin-top:10px;\">\r\n        <div class=\"topic-filter-meta\">\r\n          <span class=\"topic-filter-title\">Lọc theo chủ đề bài học:</span>\r\n          <span id=\"setup-topic-summary\" class=\"topic-filter-summary\"></span>\r\n        </div>\r\n        <div id=\"setup-topic-chips\" class=\"topic-chips-bar\" role=\"tablist\" aria-label=\"Bộ lọc chủ đề bài học\"></div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Hidden compatibility elements for existing logic -->\r\n    <input type=\"hidden\" id=\"nick\" value=\"\">\r\n    <input type=\"hidden\" id=\"class-name\" value=\"\">\r\n    <select id=\"ss\" style=\"display:none;\" onchange=\"updateSetupQuestionCount()\"></select>\r\n    <input id=\"cnt-display\" type=\"hidden\" value=\"0\">\r\n\r\n    <!-- Grid of sets matching the user image -->\r\n    <div id=\"setup-sets-grid\" class=\"setup-sets-grid\"></div>\r\n\r\n    <!-- MODAL: HỎI TÊN VÀ LỚP KHI NHẤP VÀO BỘ CÂU HỎI -->\r\n    <dialog id=\"start-quiz-dialog\" class=\"writing-modal setup-start-modal\">\r\n      <div class=\"writing-modal-header\">\r\n        <div class=\"writing-modal-title\">\r\n          <h3 id=\"start-dialog-heading\">Thông tin người học</h3>\r\n        </div>\r\n        <button class=\"btn sm gh\" type=\"button\" onclick=\"closeStartQuizModal()\" aria-label=\"Đóng\">✕</button>\r\n      </div>\r\n      \r\n      <form id=\"start-quiz-form\" onsubmit=\"handleStartQuizSubmit(event)\" class=\"writing-modal-form-wrap\">\r\n        <input type=\"hidden\" id=\"start-quiz-set-id\">\r\n        \r\n        <div class=\"writing-modal-body\" style=\"padding: 20px 24px;\">\r\n          <!-- Thông tin bộ đề đang chọn -->\r\n          <div class=\"setup-modal-set-preview\" id=\"start-modal-preview\">\r\n            <span class=\"setup-modal-pill\" id=\"start-modal-set-badge\">10 câu</span>\r\n            <h4 id=\"start-modal-set-title\" style=\"margin: 6px 0 0; font-size: 18px; font-weight: 800; line-height: 1.35;\"></h4>\r\n            <span id=\"start-modal-set-topic\" class=\"mut\" style=\"font-size: 13px; font-weight: 600; display: block; margin-top: 4px;\"></span>\r\n          </div>\r\n\r\n          <div style=\"margin-top: 18px;\">\r\n            <label for=\"start-nick\" style=\"font-weight: 700; display: block; margin-bottom: 6px; font-size: 14px;\">\r\n              Tên học sinh / Biệt danh <span style=\"color:var(--red)\">*</span>\r\n            </label>\r\n            <input type=\"text\" id=\"start-nick\" required maxlength=\"20\" placeholder=\"Nhập tên của bạn...\" style=\"font-size: 15px; padding: 11px 14px; width: 100%;\">\r\n          </div>\r\n\r\n          <div style=\"margin-top: 14px;\">\r\n            <label for=\"start-class-name\" style=\"font-weight: 700; display: block; margin-bottom: 6px; font-size: 14px;\">\r\n              Lớp (không bắt buộc)\r\n            </label>\r\n            <input type=\"text\" id=\"start-class-name\" maxlength=\"30\" placeholder=\"Ví dụ: 11A1, 10A2...\" style=\"font-size: 15px; padding: 11px 14px; width: 100%;\">\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"writing-modal-footer\">\r\n          <button type=\"button\" class=\"btn gh\" onclick=\"closeStartQuizModal()\">Hủy</button>\r\n          <button type=\"submit\" class=\"btn au\" style=\"font-weight: 800;\">▶ Bắt đầu làm bài</button>\r\n        </div>\r\n      </form>\r\n    </dialog>\r\n  </div>\r\n</section>",
  "screen-game": "<!-- SCREEN 4: GAMEPLAY -->\r\n<section id=\"s-game\" class=\"scr\">\r\n  <div class=\"wrap\">\r\n    <div class=\"hud\">\r\n      <div class=\"hud-pill\">⭐ <span id=\"hs\">0</span></div>\r\n      <div class=\"hud-pill\">🔥 x<span id=\"hc\">0</span></div>\r\n      <div class=\"hud-pill\" id=\"ht\" style=\"display:none;\">⏱ 20s</div>\r\n      <div class=\"hud-pill\" id=\"hp\">1/10</div>\r\n      <button class=\"btn gh sm\" id=\"btn-projector-toggle\" onclick=\"toggleProjectorMode()\" style=\"margin-left:auto;\" title=\"Chế độ máy chiếu\">🖥️ Máy chiếu</button>\r\n      <button class=\"btn gh sm\" onclick=\"go('home')\">🚪 Thoát</button>\r\n    </div>\r\n\r\n    <div class=\"bar\"><i id=\"pb\"></i></div>\r\n\r\n    <!-- BOSS HUD (HIDDEN) -->\r\n    <div id=\"boss\" class=\"card boss-hud-card\" hidden style=\"display:none !important;\">\r\n      <div class=\"boss-player-side\">\r\n        <span class=\"face pl\">🧙‍♂️</span>\r\n        <span class=\"boss-player-title\">Chiến Binh</span>\r\n      </div>\r\n      <div class=\"boss-center-bar\">\r\n        <div style=\"display:flex; justify-content:space-between; align-items:center; margin-bottom:4px;\">\r\n          <b class=\"boss-name-tag\">🐉 Thần Long Cổ Văn (Thủ Lĩnh)</b>\r\n          <span id=\"hpt\" class=\"boss-hp-tag\">Sinh lực: 100/100</span>\r\n        </div>\r\n        <div class=\"bar hp\" style=\"margin:4px 0;\"><i id=\"hpb\" style=\"width:100%\"></i></div>\r\n        <small class=\"mut\" style=\"font-size:12px;\">Trả lời đúng để tung chiêu thức chiến thắng Thần Long!</small>\r\n      </div>\r\n      <div class=\"boss-avatar-wrap\">\r\n        <div class=\"boss-avatar-cartoon\" id=\"boss-dragon-avatar\">🐉</div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- QUESTION CARD -->\r\n    <div class=\"card\" id=\"q\"></div>\r\n    \r\n  </div>\r\n</section>",
  "screen-res": "<!-- SCREEN 5: RESULTS -->\r\n<section id=\"s-res\" class=\"scr\">\r\n  <div class=\"wrap\">\r\n    <div class=\"hero\">\r\n      <h1 id=\"rt\">Kết quả bài làm</h1>\r\n      <p id=\"rn\" class=\"mut\" style=\"font-size:18px;\"></p>\r\n    </div>\r\n    <div class=\"card\" style=\"text-align:center;\">\r\n      <p id=\"score-save-status\" role=\"status\" aria-live=\"polite\" style=\"margin:0 0 10px;\">Đang lưu kết quả bảng xếp hạng...</p>\r\n      <button class=\"btn gh sm\" id=\"score-save-retry\" onclick=\"saveScoreToLeaderboard()\" hidden>↻ Thử lưu lại</button>\r\n    </div>\r\n    <div class=\"g3\" id=\"rs\" style=\"margin-bottom:24px;\"></div>\r\n\r\n    <div style=\"display:flex; flex-wrap:wrap; gap:12px; justify-content:center;\">\r\n      <button class=\"btn au\" onclick=\"replay()\">Làm lại</button>\r\n      <button class=\"btn cy\" onclick=\"go('setup')\">Chọn bộ khác</button>\r\n      <button class=\"btn gh\" onclick=\"go('home')\">Trang chủ</button>\r\n    </div>\r\n\r\n    <h2 style=\"margin-top:32px;\">Chi tiết từng câu hỏi</h2>\r\n    <div id=\"rv\"></div>\r\n  </div>\r\n</section>",
  "screen-writing": "<!-- SCREEN 5: WRITING PRACTICE (LUYỆN VIẾT) -->\n<section id=\"s-writing\" class=\"scr\">\n  <div class=\"wrap writing-wrap\">\n\n    <!-- VIEW 1: DANH SÁCH BỘ ĐỀ LUYỆN VIẾT -->\n    <div id=\"writing-list-view\">\n      <!-- Cartoon Hero Banner -->\n      <div class=\"writing-hero-banner\">\n        <div class=\"writing-hero-content\">\n          <h1 style=\"font-size:clamp(22px, 3.5vw, 28px); margin:0 0 4px; font-weight:800;\">Luyện viết văn theo dàn ý</h1>\n          <p class=\"writing-hero-desc\">Rèn luyện kỹ năng viết văn theo cấu trúc mở bài, thân bài, kết bài và các dạng đề chuẩn.</p>\n        </div>\n      </div>\n\n      <!-- Action & Filters Bar -->\n      <div class=\"writing-control-bar card\">\n        <div class=\"writing-control-top\">\n          <div class=\"writing-search-box\" style=\"flex:1;\">\n            <span class=\"writing-search-icon\">🔍</span>\n            <input type=\"text\" id=\"writing-search-input\" placeholder=\"Tìm kiếm bộ đề theo tên, dạng đề hoặc chủ đề...\" oninput=\"onWritingSearchInput()\">\n          </div>\n        </div>\n\n        <div class=\"writing-category-filter\">\n          <div class=\"writing-filter-chips-wrap\">\n            <span class=\"writing-filter-label\">Chủ đề:</span>\n            <div class=\"writing-category-chips\" id=\"writing-category-chips\"></div>\n          </div>\n          <div class=\"writing-category-actions\">\n            <button class=\"btn cy sm\" type=\"button\" onclick=\"promptAddNewCategory()\" title=\"Tạo thêm chủ đề mới\">\n              + Thêm chủ đề\n            </button>\n            <button class=\"btn no sm\" type=\"button\" onclick=\"promptDeleteCurrentCategory()\" title=\"Xóa chủ đề (có xác nhận)\">\n              ✕ Xóa chủ đề\n            </button>\n            <button class=\"btn au sm\" type=\"button\" onclick=\"openCreateWritingSetModal()\" title=\"Tạo bộ đề mới\">\n              + Thêm bộ mới\n            </button>\n          </div>\n        </div>\n      </div>\n\n      <!-- Container danh sách các bộ đề (sắp xếp và gom nhóm theo chủ đề) -->\n      <div id=\"writing-sets-container\"></div>\n    </div>\n\n    <!-- VIEW 2: PHÒNG LUYỆN VIẾT (SPLIT SCREEN WORKSPACE) -->\n    <div id=\"writing-workspace-view\" style=\"display:none;\">\n      <!-- Workspace Navigation Bar -->\n      <div class=\"writing-workspace-nav\">\n        <button class=\"btn gh sm\" onclick=\"exitWritingWorkspace()\">\n          <span>←</span> <span>Trở về danh sách đề</span>\n        </button>\n        <div class=\"writing-workspace-title-box\">\n          <h3 id=\"workspace-set-title\">Đề bài luyện viết</h3>\n          <span id=\"workspace-set-badge\" class=\"tag ok\">Nghị luận xã hội</span>\n        </div>\n        <div class=\"writing-workspace-actions\">\n          <button class=\"btn no sm\" onclick=\"deleteCurrentOpenedSet()\" title=\"Xóa bộ đề này khỏi danh sách\">\n            <span>🗑️</span> <span>Xóa đề này</span>\n          </button>\n          <button class=\"btn gh sm\" onclick=\"resetCurrentWritingDraft()\" title=\"Xóa nội dung đang viết để làm lại từ đầu\">\n            <span>🔄</span> <span>Xóa viết lại</span>\n          </button>\n        </div>\n      </div>\n\n      <!-- Split Layout Container -->\n      <div class=\"writing-split-container\" id=\"writing-split-container\">\n        \n        <!-- LEFT PANEL: Đề bài & Dàn ý ngữ liệu -->\n        <div class=\"writing-left-panel\" id=\"writing-left-panel\">\n          <div class=\"writing-panel-scroll\">\n            \n            <!-- Hộp đề bài -->\n            <div class=\"writing-prompt-card\">\n              <div class=\"writing-prompt-header\">\n                <span class=\"writing-prompt-tag\">Đề bài</span>\n              </div>\n              <div class=\"writing-prompt-text-wrapper\">\n                <p id=\"workspace-prompt-text\" class=\"writing-prompt-text\"></p>\n                <button type=\"button\" id=\"workspace-prompt-toggle-btn\" class=\"writing-prompt-toggle\" onclick=\"togglePromptExpand()\">Xem thêm</button>\n              </div>\n            </div>\n\n            <!-- Hộp gợi ý dàn ý / Luận điểm tham khảo -->\n            <div class=\"writing-outline-card\" id=\"workspace-outline-card\">\n              <div class=\"writing-outline-header\">\n                <span>Dàn ý định hướng</span>\n              </div>\n              <div class=\"writing-outline-content\" id=\"workspace-outline-content\"></div>\n            </div>\n\n          </div>\n        </div>\n\n        <!-- RESIZE SPLITTER / DIVIDER -->\n        <div class=\"writing-splitter\" id=\"writing-splitter\" title=\"Kéo để thay đổi độ rộng 2 cột\">\n          <div class=\"writing-splitter-handle\"></div>\n        </div>\n\n        <!-- RIGHT PANEL: Không gian viết bài theo từng phần dàn ý -->\n        <div class=\"writing-right-panel\" id=\"writing-right-panel\">\n          \n          <!-- Header thanh công cụ phải -->\n          <div class=\"writing-editor-header\">\n            <div class=\"writing-sample-toggle-wrap\">\n              <span class=\"writing-sample-label\">Bài văn mẫu tham khảo</span>\n              <label class=\"writing-switch\">\n                <input type=\"checkbox\" id=\"writing-sample-toggle\" onchange=\"toggleSampleDisplay(this.checked)\">\n                <span class=\"writing-slider\"></span>\n              </label>\n            </div>\n            <div class=\"writing-word-count-badge\">\n              Tổng số từ: <b id=\"workspace-total-words\">0</b>\n            </div>\n          </div>\n\n          <!-- Danh sách các ô viết theo từng phần của Dàn ý -->\n          <div class=\"writing-sections-list\" id=\"writing-sections-list\"></div>\n\n          <!-- Bottom Sticky Action Bar -->\n          <div class=\"writing-bottom-bar\">\n            <div class=\"writing-timer-box\">\n              <span class=\"writing-timer-icon\">⏱️</span>\n              <span class=\"writing-timer-label\">Thời gian:</span>\n              <b class=\"writing-timer-value\" id=\"workspace-timer-display\">00:00:00</b>\n              <button class=\"writing-timer-btn\" id=\"workspace-timer-btn\" onclick=\"toggleWritingTimer()\" title=\"Tạm dừng / Tiếp tục\">⏸</button>\n            </div>\n\n            <div class=\"writing-bottom-buttons\">\n              <button class=\"writing-btn-clear\" type=\"button\" onclick=\"resetCurrentWritingDraft()\" title=\"Xóa toàn bộ nội dung đang viết\">\n                <span>Xóa bài làm</span>\n              </button>\n              <button class=\"writing-btn-save\" type=\"button\" onclick=\"saveCurrentWritingDraft(true)\">\n                <span>Lưu bài viết</span>\n              </button>\n              <button class=\"writing-btn-review\" type=\"button\" onclick=\"openWritingReviewModal()\">\n                <span>Xem &amp; Xuất bài</span>\n              </button>\n            </div>\n          </div>\n\n        </div>\n\n      </div>\n    </div>\n\n  </div>\n</section>\n\n<!-- MODAL 1: TẠO / CHỈNH SỬA BỘ ĐỀ LUYỆN VIẾT -->\n<dialog id=\"writing-set-dialog\" class=\"writing-modal writing-set-modal-large\">\n  <div class=\"writing-modal-header\">\n    <div class=\"writing-modal-title\">\n      <h3 id=\"writing-dialog-heading\">Tạo bộ đề luyện viết</h3>\n    </div>\n    <button class=\"btn sm gh\" type=\"button\" onclick=\"closeCreateWritingSetModal()\" aria-label=\"Đóng\">✕</button>\n  </div>\n  \n  <form id=\"writing-set-form\" onsubmit=\"handleSaveWritingSet(event)\" class=\"writing-modal-form-wrap\">\n    <input type=\"hidden\" id=\"edit-writing-set-id\">\n\n    <div class=\"writing-modal-body\">\n      <div class=\"g2\">\n        <div>\n          <label for=\"input-set-title\">Tên bộ đề / Tiêu đề <span style=\"color:var(--red)\">*</span></label>\n          <input type=\"text\" id=\"input-set-title\" required placeholder=\"Ví dụ: Nghị luận xã hội về ý nghĩa của sự sẻ chia...\">\n        </div>\n        <div>\n          <label for=\"input-set-category\">Chủ đề / Dạng đề <span style=\"color:var(--red)\">*</span></label>\n          <select id=\"input-set-category\" onchange=\"onCategorySelectChange(this.value)\">\n            <option value=\"nl-xh\">Nghị luận xã hội (200 chữ / Bài văn ngắn)</option>\n            <option value=\"nl-vh\">Nghị luận văn học (Phân tích thơ, văn xuôi)</option>\n            <option value=\"cam-thu\">Đọc hiểu &amp; Đoạn văn cảm thụ</option>\n          </select>\n        </div>\n      </div>\n\n      <div style=\"margin-top:16px;\">\n        <label for=\"input-set-prompt\">Nội dung đề bài chi tiết <span style=\"color:var(--red)\">*</span></label>\n        <textarea id=\"input-set-prompt\" required placeholder=\"Dán nội dung đề bài, câu hỏi yêu cầu tại đây...\"></textarea>\n      </div>\n\n      <!-- Dàn ý và các phần viết -->\n      <div style=\"margin-top:20px;\">\n        <div style=\"display:flex; justify-content:space-between; align-items:center; margin-bottom:8px; flex-wrap:wrap; gap:8px;\">\n          <label style=\"margin:0; font-size:15px; font-weight:700;\">\n            Dàn ý &amp; các phần bài viết (<span id=\"modal-section-count\">3</span> phần)\n          </label>\n          <div style=\"display:flex; gap:8px;\">\n            <button type=\"button\" class=\"btn gh sm\" onclick=\"applyQuickOutlineTemplate()\">Nạp dàn ý mẫu</button>\n            <button type=\"button\" class=\"btn cy sm\" onclick=\"addNewOutlineSectionRow()\">+ Thêm phần</button>\n          </div>\n        </div>\n        <p class=\"mut\" style=\"font-size:13px; margin:0 0 12px;\">Cấu trúc chuẩn 3 phần (Mở bài, Thân bài, Kết bài) kèm hướng dẫn nội dung chi tiết.</p>\n        \n        <div id=\"modal-sections-editor\" class=\"modal-sections-editor-list\"></div>\n      </div>\n    </div>\n\n    <div class=\"writing-modal-footer\">\n      <button type=\"button\" class=\"btn gh\" onclick=\"closeCreateWritingSetModal()\">Hủy</button>\n      <button type=\"submit\" class=\"btn au\">Lưu bộ đề</button>\n    </div>\n  </form>\n</dialog>\n\n<!-- MODAL 2: XEM BÀI HOÀN CHỈNH & XUẤT BÀI -->\n<dialog id=\"writing-review-dialog\" class=\"writing-modal review-modal\">\n  <div class=\"writing-modal-header review-header\">\n    <div class=\"writing-modal-title\">\n      <h3>Tổng quan bài viết</h3>\n    </div>\n    <button class=\"btn sm gh\" type=\"button\" onclick=\"closeWritingReviewModal()\">✕</button>\n  </div>\n\n  <div class=\"writing-modal-body review-body\">\n    <!-- Stat metrics cards -->\n    <div class=\"review-stats-grid\">\n      <div class=\"review-stat-card\">\n        <span class=\"stat-num\" id=\"review-stat-words\">0</span>\n        <span class=\"stat-label\">Tổng số từ</span>\n      </div>\n      <div class=\"review-stat-card\">\n        <span class=\"stat-num\" id=\"review-stat-paragraphs\">0</span>\n        <span class=\"stat-label\">Số đoạn văn</span>\n      </div>\n      <div class=\"review-stat-card\">\n        <span class=\"stat-num\" id=\"review-stat-time\">00:00:00</span>\n        <span class=\"stat-label\">Thời gian làm</span>\n      </div>\n      <div class=\"review-stat-card\">\n        <span class=\"stat-num\" id=\"review-stat-wpm\">0</span>\n        <span class=\"stat-label\">Tốc độ (từ / phút)</span>\n      </div>\n    </div>\n\n    <!-- Combined essay text -->\n    <div class=\"review-essay-box\">\n      <div class=\"review-essay-meta\">\n        <h4 id=\"review-essay-topic\">Đề bài luyện viết</h4>\n        <span class=\"tag ok\" id=\"review-essay-tag\">Hoàn tất</span>\n      </div>\n      <div class=\"review-essay-text\" id=\"review-essay-combined-content\"></div>\n    </div>\n\n    <!-- Feedback suggestions box -->\n    <div class=\"review-feedback-box\">\n      <div class=\"review-feedback-title\">Nhận xét sơ bộ:</div>\n      <div id=\"review-feedback-content\" class=\"review-feedback-list\"></div>\n    </div>\n  </div>\n\n  <div class=\"writing-modal-footer review-footer\">\n    <button class=\"btn gh\" type=\"button\" onclick=\"copyCombinedEssayToClipboard()\">Sao chép bài viết</button>\n    <button class=\"btn cy\" type=\"button\" onclick=\"downloadCombinedEssayAsText()\">Tải tệp .txt</button>\n    <button class=\"btn au\" type=\"button\" onclick=\"closeWritingReviewModal()\">Đóng</button>\n  </div>\n</dialog>",
  "screen-reading": "<!-- SCREEN: READING COMPREHENSION (ĐỌC HIỂU NGỮ VĂN) -->\n<section id=\"s-reading\" class=\"scr\">\n  <div class=\"wrap reading-wrap\">\n\n    <!-- VIEW 1: DANH SÁCH BỘ ĐỀ ĐỌC HIỂU -->\n    <div id=\"reading-list-view\">\n      <!-- Cartoon Hero Banner -->\n      <div class=\"reading-hero-banner\">\n        <div class=\"reading-hero-content\">\n          <h1 style=\"font-size:clamp(22px, 3.5vw, 28px); margin:0 0 4px; font-weight:800;\">Luyện Đọc hiểu Ngữ Văn</h1>\n          <p class=\"reading-hero-desc\">Rèn luyện kỹ năng đọc hiểu văn bản, nhận diện phương thức biểu đạt, biện pháp nghệ thuật và phát triển tư duy phản biện.</p>\n        </div>\n      </div>\n\n      <!-- Action & Filters Bar -->\n      <div class=\"reading-control-bar card\">\n        <div class=\"reading-control-top\">\n          <div class=\"reading-search-box\">\n            <span class=\"reading-search-icon\">🔍</span>\n            <input type=\"text\" id=\"reading-search-input\" placeholder=\"Tìm kiếm bộ đề đọc hiểu theo tên bài, tác giả hoặc thể loại...\" oninput=\"onReadingSearchInput()\">\n          </div>\n        </div>\n\n        <div class=\"reading-category-filter\">\n          <div class=\"reading-filter-chips-wrap\">\n            <span class=\"reading-filter-label\">Chủ đề:</span>\n            <div class=\"reading-category-chips\" id=\"reading-category-chips\"></div>\n          </div>\n          <div class=\"reading-category-actions\">\n            <button class=\"btn cy sm\" type=\"button\" onclick=\"promptAddNewReadingCategory()\" title=\"Tạo thêm chủ đề mới\">\n              + Thêm chủ đề\n            </button>\n            <button class=\"btn no sm\" type=\"button\" onclick=\"promptDeleteCurrentReadingCategory()\" title=\"Xóa chủ đề\">\n              ✕ Xóa chủ đề\n            </button>\n            <button class=\"btn au sm\" type=\"button\" onclick=\"openCreateReadingSetModal()\" title=\"Tạo đề đọc hiểu mới\">\n              + Thêm đề mới\n            </button>\n          </div>\n        </div>\n      </div>\n\n      <!-- Container danh sách các bộ đề đọc hiểu (sắp xếp theo chủ đề) -->\n      <div id=\"reading-sets-container\"></div>\n    </div>\n\n    <!-- VIEW 2: PHÒNG ĐỌC HIỂU & LÀM BÀI (SPLIT SCREEN WORKSPACE) -->\n    <div id=\"reading-workspace-view\" style=\"display:none;\">\n      <!-- Workspace Navigation Bar -->\n      <div class=\"reading-workspace-nav\">\n        <button class=\"btn gh sm\" onclick=\"exitReadingWorkspace()\">\n          <span>←</span> <span>Trở về danh sách đề</span>\n        </button>\n        <div class=\"reading-workspace-title-box\">\n          <h3 id=\"reading-workspace-set-title\">Đề bài đọc hiểu</h3>\n          <span id=\"reading-workspace-set-badge\" class=\"tag cy\">Thơ hiện đại</span>\n        </div>\n        <div class=\"reading-workspace-actions\">\n          <button class=\"btn gh sm\" onclick=\"toggleReadingAnswersGuide()\" id=\"btn-toggle-reading-answers\" title=\"Bật/Tắt hiển thị đáp án gợi ý\">\n            <span>💡</span> <span>Xem gợi ý đáp án</span>\n          </button>\n          <button class=\"btn gh sm\" onclick=\"resetCurrentReadingDraft()\" title=\"Xóa toàn bộ câu trả lời để làm lại từ đầu\">\n            <span>🔄</span> <span>Làm lại</span>\n          </button>\n          <button class=\"btn cy sm\" onclick=\"openEditReadingSetModal(currentReadingSetId)\" title=\"Chỉnh sửa đề bài này\">\n            <span>✏️</span> <span>Sửa đề</span>\n          </button>\n          <button class=\"btn no sm\" onclick=\"deleteCurrentOpenedReadingSet()\" title=\"Xóa đề này khỏi danh sách\">\n            <span>🗑️</span> <span>Xóa đề</span>\n          </button>\n          <button class=\"btn au sm\" onclick=\"submitReadingAnswers()\" title=\"Nộp bài và xem đánh giá chi tiết\">\n            <span>✅</span> <span>Nộp bài làm</span>\n          </button>\n        </div>\n      </div>\n\n      <!-- Split Layout Container -->\n      <div class=\"reading-split-container\" id=\"reading-split-container\">\n        <!-- Cột trái: Văn bản / Ngữ liệu đọc hiểu -->\n        <div class=\"reading-passage-panel card\">\n          <div class=\"reading-panel-header\">\n            <div class=\"reading-panel-title\">\n              <span class=\"reading-panel-icon\">📜</span>\n              <h4>Văn bản / Ngữ liệu đọc hiểu</h4>\n            </div>\n            <div class=\"reading-text-tools\">\n              <button class=\"btn gh sm btn-icon-only\" type=\"button\" onclick=\"changePassageFontSize(-1)\" title=\"Giảm cỡ chữ\">A-</button>\n              <button class=\"btn gh sm btn-icon-only\" type=\"button\" onclick=\"changePassageFontSize(1)\" title=\"Tăng cỡ chữ\">A+</button>\n            </div>\n          </div>\n          \n          <div class=\"reading-passage-content-wrap\" id=\"reading-passage-scroll\">\n            <div class=\"reading-passage-meta\" id=\"reading-passage-meta\">\n              <span class=\"reading-meta-tag\" id=\"reading-passage-genre\"></span>\n              <span class=\"reading-meta-author\" id=\"reading-passage-author\"></span>\n            </div>\n            <article class=\"reading-passage-body\" id=\"reading-passage-text\">\n              <!-- Nội dung văn bản đọc hiểu -->\n            </article>\n            <div class=\"reading-passage-source\" id=\"reading-passage-source\">\n              <!-- Nguồn trích dẫn -->\n            </div>\n          </div>\n        </div>\n\n        <!-- Cột phải: Hệ thống câu hỏi & Trả lời -->\n        <div class=\"reading-questions-panel card\">\n          <div class=\"reading-panel-header\">\n            <div class=\"reading-panel-title\">\n              <span class=\"reading-panel-icon\">✍️</span>\n              <h4>Hệ thống câu hỏi (<span id=\"reading-q-count\">0</span> câu)</h4>\n            </div>\n            <span class=\"reading-save-status\" id=\"reading-save-status\">💾 Tự động lưu</span>\n          </div>\n\n          <div class=\"reading-questions-list\" id=\"reading-questions-list\">\n            <!-- Danh sách câu hỏi render bởi JS -->\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <!-- MODAL: TẠO / SỬA ĐỀ ĐỌC HIỂU -->\n    <dialog id=\"reading-edit-modal\" class=\"writing-modal reading-modal\">\n      <div class=\"writing-modal-header\">\n        <div class=\"writing-modal-title\">\n          <h3 id=\"reading-modal-title\">Thêm bộ đề đọc hiểu mới</h3>\n        </div>\n        <button class=\"btn sm gh\" type=\"button\" onclick=\"closeReadingEditModal()\" aria-label=\"Đóng\">✕</button>\n      </div>\n\n      <form id=\"reading-edit-form\" onsubmit=\"handleReadingFormSubmit(event)\" class=\"writing-modal-form-wrap\">\n        <input type=\"hidden\" id=\"reading-form-id\">\n\n        <div class=\"writing-modal-body\">\n          <!-- Hàng 1: Tên đề bài & Chủ đề -->\n          <div class=\"g2\" style=\"margin-bottom:14px;\">\n            <div>\n              <label for=\"reading-form-title\" style=\"font-weight:700; display:block; margin-bottom:5px;\">\n                Tên đề bài / Tác phẩm <span style=\"color:var(--red)\">*</span>\n              </label>\n              <input type=\"text\" id=\"reading-form-title\" required placeholder=\"Ví dụ: Đất Nước, Bếp lửa, Bức thư gửi con...\" style=\"width:100%;\">\n            </div>\n            <div>\n              <label for=\"reading-form-category\" style=\"font-weight:700; display:block; margin-bottom:5px;\">\n                Chủ đề / Dạng bài <span style=\"color:var(--red)\">*</span>\n              </label>\n              <select id=\"reading-form-category\" required style=\"width:100%;\"></select>\n            </div>\n          </div>\n\n          <!-- Hàng 2: Tác giả & Thể loại -->\n          <div class=\"g2\" style=\"margin-bottom:14px;\">\n            <div>\n              <label for=\"reading-form-author\" style=\"font-weight:700; display:block; margin-bottom:5px;\">\n                Tác giả / Xuất xứ\n              </label>\n              <input type=\"text\" id=\"reading-form-author\" placeholder=\"Ví dụ: Nguyễn Khoa Điềm, Báo Tuổi Trẻ...\" style=\"width:100%;\">\n            </div>\n            <div>\n              <label for=\"reading-form-genre\" style=\"font-weight:700; display:block; margin-bottom:5px;\">\n                Thể loại văn bản\n              </label>\n              <input type=\"text\" id=\"reading-form-genre\" placeholder=\"Ví dụ: Thơ tự do, Truyện ngắn, Văn bản thông tin...\" style=\"width:100%;\">\n            </div>\n          </div>\n\n          <!-- Ngữ liệu đọc hiểu -->\n          <div style=\"margin-bottom:16px;\">\n            <label for=\"reading-form-passage\" style=\"font-weight:700; display:block; margin-bottom:5px;\">\n              Văn bản / Ngữ liệu đọc hiểu <span style=\"color:var(--red)\">*</span>\n            </label>\n            <textarea id=\"reading-form-passage\" required rows=\"9\" placeholder=\"Dán hoặc nhập toàn bộ đoạn trích / văn bản đọc hiểu vào đây...\" style=\"width:100%; font-family:inherit; line-height:1.6;\"></textarea>\n          </div>\n\n          <!-- Nguồn trích dẫn -->\n          <div style=\"margin-bottom:18px;\">\n            <label for=\"reading-form-source\" style=\"font-weight:700; display:block; margin-bottom:5px;\">\n              Ghi chú nguồn trích dẫn\n            </label>\n            <input type=\"text\" id=\"reading-form-source\" placeholder=\"(Trích 'Tên tác phẩm', NXB Văn học, 2020, tr. 45)\" style=\"width:100%;\">\n          </div>\n\n          <!-- Danh sách câu hỏi đọc hiểu -->\n          <div class=\"reading-form-questions-section\">\n            <div style=\"display:flex; justify-content:space-between; align-items:center; margin-bottom:12px;\">\n              <h4 style=\"margin:0; font-size:16px; font-weight:800;\">Hệ thống câu hỏi đọc hiểu</h4>\n              <button type=\"button\" class=\"btn cy sm\" onclick=\"addQuestionToReadingForm()\">+ Thêm câu hỏi</button>\n            </div>\n            <div id=\"reading-form-questions-list\"></div>\n          </div>\n        </div>\n\n        <div class=\"writing-modal-footer\">\n          <button type=\"button\" class=\"btn gh\" onclick=\"closeReadingEditModal()\">Hủy</button>\n          <button type=\"submit\" class=\"btn au\" style=\"font-weight:800;\">💾 Lưu đề đọc hiểu</button>\n        </div>\n      </form>\n    </dialog>\n\n    <!-- MODAL: KẾT QUẢ / ĐÁP ÁN THAM KHẢO KHI NỘP BÀI -->\n    <dialog id=\"reading-result-modal\" class=\"writing-modal reading-modal\">\n      <div class=\"writing-modal-header\">\n        <div class=\"writing-modal-title\">\n          <h3>Kết quả bài làm &amp; Đáp án tham khảo</h3>\n        </div>\n        <button class=\"btn sm gh\" type=\"button\" onclick=\"closeReadingResultModal()\" aria-label=\"Đóng\">✕</button>\n      </div>\n\n      <div class=\"writing-modal-body\" style=\"padding:20px 24px;\">\n        <div class=\"reading-result-hero\">\n          <div style=\"font-size:36px; margin-bottom:6px;\">🎉</div>\n          <h3 style=\"margin:0 0 6px; font-weight:800;\">Đã hoàn thành bài đọc hiểu!</h3>\n          <p class=\"mut\" style=\"margin:0; font-size:14px;\">Dưới đây là phần so sánh giữa câu trả lời của bạn và đáp án/gợi ý chuẩn.</p>\n        </div>\n\n        <div id=\"reading-result-comparison-list\" style=\"margin-top:20px;\"></div>\n      </div>\n\n      <div class=\"writing-modal-footer\">\n        <button type=\"button\" class=\"btn gh\" onclick=\"closeReadingResultModal()\">Đóng</button>\n        <button type=\"button\" class=\"btn au\" onclick=\"copyReadingStudentAnswers()\">📋 Sao chép bài làm</button>\n      </div>\n    </dialog>\n\n  </div>\n</section>",
  "dialogs": "<!-- FEEDBACK DIALOG -->\n<dialog id=\"feedback-dialog\" aria-live=\"polite\">\n  <div id=\"fb\"></div>\n</dialog>\n\n<!-- CONFIRM DELETE DIALOG -->\n<dialog id=\"dlg\">\n  <p id=\"dm\" style=\"font-size:16px; font-weight:600; margin-bottom:20px;\"></p>\n  <div style=\"display:flex; gap:10px; justify-content:flex-end;\">\n    <button class=\"btn gh sm\" onclick=\"dlg.close()\">Hủy</button>\n    <button class=\"btn no sm\" id=\"dy\">Xóa</button>\n  </div>\n</dialog>\n\n<!-- AI PROMPT DIALOG -->\n<dialog id=\"prompt-dialog\">\n  <div class=\"prompt-dialog-header\">\n    <div>\n      <h2 style=\"display:flex; align-items:center; gap:8px;\">Tạo bộ câu hỏi bằng trợ lý AI</h2>\n      <p class=\"mut\" style=\"margin:4px 0 0; font-size:13px;\">Tạo câu lệnh → Gửi AI → Nhập câu hỏi vào hệ thống</p>\n    </div>\n    <button class=\"btn gh sm prompt-dialog-close\" type=\"button\"\n      onclick=\"$('#prompt-dialog').close()\" aria-label=\"Đóng cửa sổ tạo bộ câu hỏi\" title=\"Đóng\">×</button>\n  </div>\n\n  <div style=\"background:rgba(217, 169, 79, 0.12); border:1px solid var(--gold); border-radius:12px; padding:9px 13px; margin-bottom:14px; font-size:13px; line-height:1.5;\">\n    Hệ thống tạo câu lệnh chuẩn để gửi sang <b>ChatGPT, Gemini hoặc Claude</b>. Sau khi AI trả lời, bạn dán kết quả vào <b>Bước 3</b> bên dưới để tự động tạo bộ câu hỏi.\n  </div>\n\n  <!-- BƯỚC 1 -->\n  <div class=\"prompt-step-box\">\n    <div class=\"prompt-step-title\">\n      <span class=\"prompt-step-badge\">1</span>\n      <span>Thiết lập nội dung & Tạo câu lệnh</span>\n    </div>\n    \n    <label for=\"prompt-topic\" style=\"font-weight:600;\">Chủ đề / Tác phẩm / Bài học <span style=\"color:var(--gold);\">*</span></label>\n    <input id=\"prompt-topic\" type=\"text\" maxlength=\"500\"\n      placeholder=\"Ví dụ: Ông già và biển cả, Vợ nhặt, Tây Tiến, Chí Phèo...\">\n\n    <!-- TỔNG SỐ CÂU HỎI & CHIA ĐỀU -->\n    <div style=\"display:grid; grid-template-columns: 1fr auto; gap:12px; margin-top:12px; align-items:end;\">\n      <div>\n        <label for=\"prompt-question-count\" style=\"font-weight:600;\">Tổng số câu hỏi của bộ đề</label>\n        <select id=\"prompt-question-count\" onchange=\"onPromptTotalCountChange()\">\n          <option value=\"4\">4 câu</option>\n          <option value=\"5\">5 câu</option>\n          <option value=\"6\">6 câu</option>\n          <option value=\"8\">8 câu</option>\n          <option value=\"10\" selected>10 câu</option>\n          <option value=\"12\">12 câu</option>\n          <option value=\"15\">15 câu</option>\n          <option value=\"16\">16 câu</option>\n          <option value=\"20\">20 câu</option>\n          <option value=\"25\">25 câu</option>\n          <option value=\"30\">30 câu</option>\n        </select>\n      </div>\n      <div>\n        <button class=\"btn gh sm\" type=\"button\" onclick=\"autoDistributePromptTypes()\" title=\"Chia đều số câu theo các dạng đang chọn\" style=\"height:42px; padding:0 12px; font-weight:700;\">\n          Chia đều số câu\n        </button>\n      </div>\n    </div>\n\n    <!-- PHÂN BỔ SỐ CÂU THEO TỪNG DẠNG -->\n    <fieldset style=\"margin-top:12px; padding:12px 14px; border:1px solid var(--stroke); border-radius:12px; background:var(--bg);\">\n      <div style=\"display:flex; justify-content:space-between; align-items:center; margin-bottom:8px; flex-wrap:wrap; gap:6px;\">\n        <legend style=\"padding:0 6px; font-weight:700; font-size:12px; color:var(--mut); margin:0;\">PHÂN BỔ SỐ CÂU THEO TỪNG DẠNG</legend>\n        <span id=\"prompt-count-status-badge\" style=\"font-size:11.5px; font-weight:700; padding:2px 8px; border-radius:6px;\"></span>\n      </div>\n\n      <div style=\"display:flex; flex-direction:column; gap:8px;\">\n        <!-- Dạng 1: Trắc nghiệm -->\n        <div class=\"prompt-type-item\" style=\"display:flex; align-items:center; justify-content:space-between; gap:10px; padding:7px 12px; background:var(--bg-card); border:1px solid var(--stroke); border-radius:10px;\">\n          <label style=\"margin:0; display:flex; align-items:center; gap:8px; cursor:pointer; font-weight:600; font-size:13.5px; flex:1;\">\n            <input type=\"checkbox\" id=\"prompt-type-cb-mc\" name=\"prompt-question-type\" value=\"mc\" checked onchange=\"onPromptTypeToggle('mc')\" style=\"width:auto; margin:0;\">\n            <span>Trắc nghiệm (4 lựa chọn)</span>\n          </label>\n          <div style=\"display:flex; align-items:center; gap:4px;\">\n            <button type=\"button\" class=\"btn gh sm\" onclick=\"adjustPromptTypeCount('mc', -1)\" style=\"width:26px; height:26px; padding:0; min-height:unset; font-size:14px; font-weight:900;\">-</button>\n            <input id=\"prompt-count-mc\" type=\"number\" min=\"0\" max=\"50\" value=\"4\" oninput=\"onPromptTypeCountInput('mc')\" style=\"width:44px; text-align:center; padding:2px 4px; font-weight:800; font-size:13.5px; height:26px; border-radius:6px;\">\n            <button type=\"button\" class=\"btn gh sm\" onclick=\"adjustPromptTypeCount('mc', 1)\" style=\"width:26px; height:26px; padding:0; min-height:unset; font-size:14px; font-weight:900;\">+</button>\n            <span style=\"font-size:12px; color:var(--mut); min-width:22px;\">câu</span>\n          </div>\n        </div>\n\n        <!-- Dạng 2: Đúng / Sai -->\n        <div class=\"prompt-type-item\" style=\"display:flex; align-items:center; justify-content:space-between; gap:10px; padding:7px 12px; background:var(--bg-card); border:1px solid var(--stroke); border-radius:10px;\">\n          <label style=\"margin:0; display:flex; align-items:center; gap:8px; cursor:pointer; font-weight:600; font-size:13.5px; flex:1;\">\n            <input type=\"checkbox\" id=\"prompt-type-cb-tf\" name=\"prompt-question-type\" value=\"tf\" checked onchange=\"onPromptTypeToggle('tf')\" style=\"width:auto; margin:0;\">\n            <span>Đúng / Sai (4 ý)</span>\n          </label>\n          <div style=\"display:flex; align-items:center; gap:4px;\">\n            <button type=\"button\" class=\"btn gh sm\" onclick=\"adjustPromptTypeCount('tf', -1)\" style=\"width:26px; height:26px; padding:0; min-height:unset; font-size:14px; font-weight:900;\">-</button>\n            <input id=\"prompt-count-tf\" type=\"number\" min=\"0\" max=\"50\" value=\"2\" oninput=\"onPromptTypeCountInput('tf')\" style=\"width:44px; text-align:center; padding:2px 4px; font-weight:800; font-size:13.5px; height:26px; border-radius:6px;\">\n            <button type=\"button\" class=\"btn gh sm\" onclick=\"adjustPromptTypeCount('tf', 1)\" style=\"width:26px; height:26px; padding:0; min-height:unset; font-size:14px; font-weight:900;\">+</button>\n            <span style=\"font-size:12px; color:var(--mut); min-width:22px;\">câu</span>\n          </div>\n        </div>\n\n        <!-- Dạng 3: Trả lời ngắn -->\n        <div class=\"prompt-type-item\" style=\"display:flex; align-items:center; justify-content:space-between; gap:10px; padding:7px 12px; background:var(--bg-card); border:1px solid var(--stroke); border-radius:10px;\">\n          <label style=\"margin:0; display:flex; align-items:center; gap:8px; cursor:pointer; font-weight:600; font-size:13.5px; flex:1;\">\n            <input type=\"checkbox\" id=\"prompt-type-cb-short\" name=\"prompt-question-type\" value=\"short\" checked onchange=\"onPromptTypeToggle('short')\" style=\"width:auto; margin:0;\">\n            <span>Trả lời ngắn</span>\n          </label>\n          <div style=\"display:flex; align-items:center; gap:4px;\">\n            <button type=\"button\" class=\"btn gh sm\" onclick=\"adjustPromptTypeCount('short', -1)\" style=\"width:26px; height:26px; padding:0; min-height:unset; font-size:14px; font-weight:900;\">-</button>\n            <input id=\"prompt-count-short\" type=\"number\" min=\"0\" max=\"50\" value=\"2\" oninput=\"onPromptTypeCountInput('short')\" style=\"width:44px; text-align:center; padding:2px 4px; font-weight:800; font-size:13.5px; height:26px; border-radius:6px;\">\n            <button type=\"button\" class=\"btn gh sm\" onclick=\"adjustPromptTypeCount('short', 1)\" style=\"width:26px; height:26px; padding:0; min-height:unset; font-size:14px; font-weight:900;\">+</button>\n            <span style=\"font-size:12px; color:var(--mut); min-width:22px;\">câu</span>\n          </div>\n        </div>\n\n        <!-- Dạng 4: Điền từ -->\n        <div class=\"prompt-type-item\" style=\"display:flex; align-items:center; justify-content:space-between; gap:10px; padding:7px 12px; background:var(--bg-card); border:1px solid var(--stroke); border-radius:10px;\">\n          <label style=\"margin:0; display:flex; align-items:center; gap:8px; cursor:pointer; font-weight:600; font-size:13.5px; flex:1;\">\n            <input type=\"checkbox\" id=\"prompt-type-cb-fill\" name=\"prompt-question-type\" value=\"fill\" checked onchange=\"onPromptTypeToggle('fill')\" style=\"width:auto; margin:0;\">\n            <span>Điền từ vào chỗ trống</span>\n          </label>\n          <div style=\"display:flex; align-items:center; gap:4px;\">\n            <button type=\"button\" class=\"btn gh sm\" onclick=\"adjustPromptTypeCount('fill', -1)\" style=\"width:26px; height:26px; padding:0; min-height:unset; font-size:14px; font-weight:900;\">-</button>\n            <input id=\"prompt-count-fill\" type=\"number\" min=\"0\" max=\"50\" value=\"2\" oninput=\"onPromptTypeCountInput('fill')\" style=\"width:44px; text-align:center; padding:2px 4px; font-weight:800; font-size:13.5px; height:26px; border-radius:6px;\">\n            <button type=\"button\" class=\"btn gh sm\" onclick=\"adjustPromptTypeCount('fill', 1)\" style=\"width:26px; height:26px; padding:0; min-height:unset; font-size:14px; font-weight:900;\">+</button>\n            <span style=\"font-size:12px; color:var(--mut); min-width:22px;\">câu</span>\n          </div>\n        </div>\n      </div>\n\n      <!-- TỔNG KẾT & CẢNH BÁO TỔNG SỐ CÂU -->\n      <div id=\"prompt-sum-indicator\" style=\"margin-top:10px; font-size:12.5px; padding:7px 12px; border-radius:8px; display:flex; justify-content:space-between; align-items:center; font-weight:600;\"></div>\n    </fieldset>\n\n    <label for=\"prompt-source\" style=\"margin-top:12px; font-weight:600;\">\n      Văn bản / Ngữ liệu đọc hiểu <span style=\"font-weight:400; color:var(--mut); font-size:12px;\">(Không bắt buộc)</span>\n    </label>\n    <textarea id=\"prompt-source\" maxlength=\"20000\"\n      placeholder=\"Dán đoạn trích nếu muốn câu hỏi đọc hiểu bám sát ngữ liệu riêng. Nếu để trống, AI sẽ tự động tạo câu hỏi dựa trên kiến thức tác phẩm chuẩn theo SGK...\"\n      style=\"min-height:85px;\"></textarea>\n    <div style=\"display:flex; justify-content:space-between; align-items:center; margin-top:4px; font-size:12px;\">\n      <span id=\"prompt-source-guidance\" class=\"mut\" aria-live=\"polite\">💡 Để trống nếu muốn AI tự động dùng kiến thức SGK.</span>\n      <span id=\"prompt-source-count\" class=\"mut\" aria-live=\"polite\"></span>\n    </div>\n\n    <div style=\"margin-top:12px;\">\n      <button class=\"btn au\" type=\"button\" onclick=\"buildQuestionPrompt()\" style=\"width:100%; justify-content:center; font-weight:700; padding:11px;\">\n        Tạo câu lệnh AI\n      </button>\n    </div>\n  </div>\n\n  <!-- BƯỚC 2 -->\n  <div class=\"prompt-step-box\">\n    <div class=\"prompt-step-title\">\n      <span class=\"prompt-step-badge\">2</span>\n      <span>Gửi câu lệnh sang AI để nhận câu hỏi</span>\n    </div>\n    \n    <label for=\"prompt-output\" style=\"font-weight:600; font-size:13px;\">Câu lệnh AI đã sẵn sàng:</label>\n    <textarea id=\"prompt-output\" readonly style=\"min-height:110px; font-size:12px; font-family:monospace;\"\n      placeholder=\"Câu lệnh sẽ xuất hiện tại đây sau khi bạn nhấn nút ở Bước 1...\"></textarea>\n    \n    <div style=\"display:flex; flex-wrap:wrap; gap:8px; margin-top:8px; align-items:center;\">\n      <button class=\"btn cy sm\" type=\"button\" onclick=\"copyQuestionPrompt()\">📋 Sao chép câu lệnh</button>\n      <span style=\"font-size:12px; color:var(--mut); margin:0 4px;\">Hoặc mở nhanh AI:</span>\n      <button class=\"btn gh sm\" type=\"button\" onclick=\"openExternalAI('chatgpt')\">Mở ChatGPT</button>\n      <button class=\"btn gh sm\" type=\"button\" onclick=\"openExternalAI('gemini')\">Mở Gemini</button>\n      <button class=\"btn gh sm\" type=\"button\" onclick=\"openExternalAI('claude')\">Mở Claude</button>\n    </div>\n  </div>\n\n  <!-- BƯỚC 3 -->\n  <div class=\"prompt-step-box\" style=\"margin-bottom:0;\">\n    <div class=\"prompt-step-title\">\n      <span class=\"prompt-step-badge\">3</span>\n      <span>Dán kết quả từ AI & Nhập vào hệ thống</span>\n    </div>\n    \n    <label for=\"prompt-result\" style=\"font-weight:600; font-size:13px;\">\n      Dán kết quả tại đây:\n      <span style=\"font-weight:400; color:var(--mut); font-size:12px;\">(Hỗ trợ JSON hoặc văn bản trắc nghiệm: Câu 1: A, B, C, D...)</span>\n    </label>\n    <textarea id=\"prompt-result\" maxlength=\"150000\"\n      placeholder=\"Dán câu trả lời của ChatGPT/Gemini/Claude vào đây...\"\n      style=\"min-height:110px;\"></textarea>\n\n    <div style=\"display:flex; gap:10px; justify-content:flex-end; margin-top:14px;\">\n      <button class=\"btn gh sm\" type=\"button\" onclick=\"$('#prompt-dialog').close()\">Đóng</button>\n      <button class=\"btn au\" type=\"button\" onclick=\"importPromptQuestionSet()\" style=\"font-weight:700;\">\n        Nhập bộ câu hỏi\n      </button>\n    </div>\n  </div>\n</dialog>\n\n<!-- TOAST & BACK TO TOP -->\n<div id=\"toast\" role=\"status\"></div>\n<button id=\"back-to-top\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\" aria-label=\"Về đầu trang\" title=\"Về đầu trang\">↑</button>"
};

(function renderModularComponents() {
  document.querySelectorAll('[data-component]').forEach(placeholder => {
    const name = placeholder.getAttribute('data-component');
    const markup = window.COMPONENTS[name];
    if (markup) {
      const fragment = document.createRange().createContextualFragment(markup);
      placeholder.replaceWith(fragment);
    }
  });
})();
